{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table maplemonk.CC_Sales_Cost_Source as with Sessions as ( ( select date date, trim(region) as region, upper(trim(shop_name)) Brand, trim(channel) marketing_channel, \'WEBSITE\' as Marketplace, sum(sessions) Sessions from maplemonk.cc_ga_sessions_consolidated group by 1,2,3,4,5 ) UNION ALL ( Select cast(DATAENDTIME as date) Date, trim(country) as region, trim(ifnull(mp.brand,\'Others\')) as brand, \'AMAZON\' as marketing_channel, \'AMAZON\' as marketplace, SUM(ifnull(cast(JSON_EXTRACT_SCALAR(trafficbyasin,\'$.sessions\') as int64),0)) as sessions From Maplemonk.CC_BR_Consolidated_GET_SALES_AND_TRAFFIC_REPORT_ASIN ts left join ( select * from `MAPLEMONK.ASIN__SKU_Mapping` wm qualify row_number() over(partition by asin order by asin) = 1 )mp on lower(ts.parentAsin) = lower(mp.asin) group by 1,2,3,4,5 ) ), returnsales as ( select cast(Return_date as date) return_date ,trim(brand) as brand ,trim(region) as region ,cast(channel as string) marketing_channel ,cast(marketplace as string) marketplace ,sum(ifnull(returned_sales,0)) TOTAL_RETURN_AMOUNT ,sum(ifnull(returned_sales,0)) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(ifnull(returned_quantity,0)) TOTAL_RETURNED_QUANTITY from maplemonk.CC_SALES_CONSOLIDATED where Return_date is not null group by 1,2,3,4,5 ), orders as ( select cast(FI.order_date as date) Date ,trim(Brand) Brand ,trim(region) as region ,cast(marketplace as string) Marketplace ,cast(FI.CHANNEL as string) marketing_CHANNEL ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when (lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') then ifnull(FI.SELLING_PRICE,0) else 0 end),0) TOTAL_SALES_EXCL_CANCL ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') then FI.order_id end)) as New_Customer_Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) as Total_New_Customers ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end)) New_Customers_EXCL_CANCL ,count(distinct FI.customer_id_final) as TOTAL_Unique_Customers ,(count(distinct FI.customer_id_final) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.customer_id_final end)) as Unique_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) as Repeat_Customers ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end))) Repeat_Customers_EXCL_CANCL ,ifnull(sum(FI.discount),0) TOTAL_DISCOUNT ,(ifnull(sum(FI.discount),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.discount end),0)) TOTAL_DISCOUNT_EXCL_CANCL ,ifnull(sum(FI.tax),0) TOTAL_TAX ,(ifnull(sum(FI.tax),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.tax end),0)) TAX_EXCL_CANCL ,ifnull(sum(FI.shipping_price),0) TOTAL_SHIPPING_PRICE ,(ifnull(sum(FI.shipping_price),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.shipping_price end),0)) SHIPPING_PRICE_EXCL_CANCL ,ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) as New_Customer_Discount ,(ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) - ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' and lower(order_status) in (\'cancelled\') then FI.discount end),0)) as New_Customer_Discount_EXCL_CANCL ,ifnull(sum(FI.quantity),0) TOTAL_QUANTITY ,(ifnull(sum(FI.quantity),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.quantity end),0)) QUANTITY_EXCL_CANCL ,ifnull(sum(case when FI.return_flag=1 then FI.quantity end),0) as Return_Quantity ,ifnull(sum(case when FI.return_flag=1 then ifnull(FI.SELLING_PRICE,0) end),0) as Return_Value ,count(distinct case when lower(order_status) in (\'cancelled\') then order_id end) Cancelled_Orders ,count(distinct case when lower(order_status) not in (\'cancelled\') and return_flag=0 then order_id end) Net_Orders ,count(distinct case when lower(order_status) in (\'delivered\') then order_id end) Delivered_Orders ,count(distinct case when lower(order_status) in (\'returned\',\'rto\') then order_id end) Returned_Orders ,count(distinct case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then order_id end) Dispatched_Orders ,count(distinct case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then order_id end) Realised_Orders ,ifnull(sum(case when lower(order_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Delivered_Revenue ,ifnull(sum(case when lower(order_status) in (\'returned\',\'rto\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Returned_Revenue ,ifnull(sum(case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) end),0) Dispatched_Revenue ,ifnull(sum(case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then ifnull(FI.SELLING_PRICE,0) end),0) Realised_Revenue ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -3 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L3M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -6 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L6M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -12 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L12M_Customers_Retained ,sum(case when lower(FI.new_customer_flag) = \'repeat\' then ifnull(FI.selling_price,0) end) Repeat_Customer_Revenue ,count(distinct case when lower(FI.payment_mode) in (\'cod\') then FI.order_id end) as COD_Orders from maplemonk.CC_SALES_CONSOLIDATED FI group by 1,2,3,4,5 ), Final_Spends as ( select Date ,trim(region) as region ,trim(brand) as brand ,case when lower(channel) like any (\'%facebook%\',\'%google%\') then \'WEBSITE\' else channel end as marketplace ,cast(channel as string) marketing_Channel ,sum(ifnull(spend,0)) AS spend ,null AS ad_impressions ,null AS ad_clicks ,null AS ad_conversions ,null AS ad_sales from maplemonk.CC_MARKETING_CONSOLIDATED group by 1,2,3,4,5 ) select coalesce(fi.Date,MC.date, SC.date,rs.return_date) as date, upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) as Marketplace, upper(coalesce(fi.marketing_channel,MC.marketing_Channel,RS.marketing_channel, SC.marketing_channel)) as Marketing_Channel, upper(coalesce(fi.Region,MC.Region,RS.Region, SC.Region)) as Region, upper(coalesce(fi.brand,MC.brand,RS.brand, SC.brand)) as brand, Total_Sales, TOTAL_SALES_EXCL_CANCL, SC.sessions, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, QUANTITY_EXCL_CANCL, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT as Return_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend as marketing_spend, COD_Orders, Repeat_Customer_Revenue, MC.ad_conversions, MC.ad_impressions, MC.ad_clicks, MC.ad_sales from orders FI full outer join Final_Spends MC on FI.Date = MC.date and lower(FI.marketing_channel)=lower(MC.marketing_channel) and lower(FI.Marketplace)=lower(MC.Marketplace) and lower(FI.Region)=lower(MC.Region) and lower(FI.brand)=lower(MC.brand) full outer join returnsales RS on RS.return_date = coalesce(FI.date, MC.date) and lower(RS.marketing_Channel) = lower(coalesce(FI.marketing_Channel,MC.marketing_channel)) and lower(RS.marketplace)=lower(coalesce(FI.marketplace,MC.marketplace)) and lower(RS.Region)=lower(coalesce(FI.Region,MC.Region)) and lower(RS.brand)=lower(coalesce(FI.brand,MC.brand)) full outer join SESSIONS SC on coalesce(FI.Date,MC.date,RS.return_date)=SC.Date and lower(coalesce(FI.Marketing_Channel,MC.marketing_channel,RS.marketing_Channel))=lower(SC.Marketing_Channel) and lower(coalesce(FI.marketplace,MC.marketplace,RS.marketplace))=lower(SC.Marketplace) and lower(coalesce(FI.Region,MC.Region,RS.Region))=lower(SC.Region) and lower(coalesce(FI.brand,MC.brand,RS.brand))=lower(SC.brand) ;",
                    "transaction": true
                }
            ) }}
